svg.script:
//!export-start
let _pb_state = true;
let _ps_cmd = '';
let _ps_label = '';
let _ps_action = 'write_bit';
let _ps_type = 'Y';
let _pn_addr = 4;
//!export-end

function postValue(id, value) {
  console.error('Not defined!', id, value);
}

let currentState = !!_pb_state;

function setText(el, text) {
  if (!el) return;
  while (el.firstChild) {
    el.removeChild(el.firstChild);
  }
  el.appendChild(document.createTextNode(text));
}

function render() {
  const offEl = document.getElementById('imgOff');
  const onEl = document.getElementById('imgOn');
  const labelEl = document.getElementById('label');

  if (offEl) offEl.setAttribute('opacity', currentState ? '0' : '1');
  if (onEl) onEl.setAttribute('opacity', currentState ? '1' : '0');
  setText(labelEl, _ps_label || '');
}

function putValue(id, value) {
  if (id === '_pb_state') {
    currentState = !!value;
    render();
  } else if (id === '_ps_label') {
    _ps_label = String(value ?? '');
    render();
  } else if (id === '_ps_action') {
    _ps_action = String(value ?? 'write_bit');
  } else if (id === '_ps_type') {
    _ps_type = String(value ?? 'Y');
  } else if (id === '_pn_addr') {
    const parsed = Number(value);
    _pn_addr = Number.isFinite(parsed) ? parsed : 4;
  }
}

function buildPayload(nextState) {
  const addr = Number.isFinite(Number(_pn_addr)) ? Number(_pn_addr) : 4;
  return JSON.stringify({
    action: _ps_action || 'write_bit',
    type: _ps_type || 'Y',
    addr: addr,
    value: !!nextState
  });
}

function sendCommand(nextState) {
  currentState = !!nextState;
  render();
  if (typeof postValue === 'function') {
    postValue('_ps_cmd', buildPayload(currentState));
  }
}

const clickTarget = document.getElementById('clickTarget');
if (clickTarget) {
  clickTarget.addEventListener('click', () => sendCommand(!currentState));
  clickTarget.style.cursor = 'pointer';
}

render();
